entries[389403] = { ["name"] = "Graceful Avoidance", ["text"] = "3.5 sec cast\nRequires Cloak\nTools: Runed Enchanting Rod\nReagents:\nChromatic Dust (8), Vibrant Shard (3)\nOptional Reagents:\nLesser Illustrious Insight (#92)\nPermanently enchants a cloak to increase your Avoidance by 4 and reduce fall damage taken by 10%. Cannot be applied to items lower than level 10.\nVendor:\nBoss Magor\nZone:\nThe Waking Shores\nDragonscale Expedition - Renown 9\nCost:\n50\n\nVendor:\nCataloger Jakes\nZone:\nThe Waking Shores\nDragonscale Expedition - Renown 9\nCost:\n50\n\nEnchant Cloak - Graceful Avoidance\n\nUse: Permanently enchants a cloak to increase your Avoidance by 4 and reduce fall damage taken by 10%. Cannot be applied to items lower than level 10.\n60" }
entries[389404] = { ["name"] = "Regenerative Leech", ["text"] = "3.5 sec cast\nRequires Cloak\nTools: Runed Enchanting Rod\nReagents:\nChromatic Dust (8), Vibrant Shard (3)\nOptional Reagents:\nLesser Illustrious Insight (#92)\nPermanently enchants a cloak to increase your Leech by 4 and heal for 1528 every 5 sec while out of combat. Cannot be applied to items lower than level 10.\nVendor:\nMurik\nZone:\nThe Azure Span\nIskaara Tuskarr - Renown 10\nCost:\n50\n\nVendor:\nRokkutuk\nZone:\nThe Azure Span\nIskaara Tuskarr - Renown 10\nCost:\n50\n\nEnchant Cloak - Regenerative Leech\n\nUse: Permanently enchants a cloak to increase your Leech by 4 and heal for 1528 every 5 sec while out of combat. Cannot be applied to items lower than level 10.\n60" }
entries[389405] = { ["name"] = "Homebound Speed", ["text"] = "3.5 sec cast\nRequires Cloak\nTools: Runed Enchanting Rod\nReagents:\nChromatic Dust (8), Vibrant Shard (3)\nOptional Reagents:\nLesser Illustrious Insight (#92)\nPermanently enchants a cloak to increase your Speed by 4 and reduce the cooldown of your Hearthstone by 3 minutes while in the Dragon Isles. Cannot be applied to items lower than level 10.\nVendor:\nDothenos\nZone:\nValdrakken\nValdrakken Accord - Renown 11\nCost:\n50\n\nVendor:\nUnatos\nZone:\nValdrakken\nValdrakken Accord - Renown 11\nCost:\n50\n\nEnchant Cloak - Homebound Speed\n\nUse: Permanently enchants a cloak to increase your Speed by 4 and reduce the cooldown of your Hearthstone by 3 minutes while in the Dragon Isles. Cannot be applied to items lower than level 10.\n60" }
entries[389406] = { ["name"] = "Titan-Touched Draconium Deposit", ["text"] = "5 yd range\n3.2 sec cast\nDraconium Deposits are a rare find upon the Dragon Isles, but they are more often spotted in rugged or hard to reach locations.\n\nThey are sometimes empowered by small Titan research constructs. Fortunately, they would sooner grant a miner their boon rather than retaliate.\n\nGain the following effect when mining:\n\nEnlightened Potential :\nSpeed increased by 15%. Gatherers specialized in Titan-Touched nodes will also have their secondary stats increased by 3%." }
entries[389407] = { ["name"] = "Furious Ragefeather", ["text"] = "Instant\nYour damaging spells have a chance to fire a Soulseeker Arrow towards your target, inflicting 0 Shadow damage over 1 min to the first enemy hit. If the target dies while affected, your next damaging spells will fire an arrow." }
